 "content": "def transform(grid):
    """Pack colored objects in left-to-right order, corner-overlapping."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top = min(y for y, _ in cells)
            left = min(x for _, x in cells)
            bottom = max(y for y, _ in cells)
            right = max(x for _, x in cells)
            shape = {(y-top, x-left) for y, x in cells}
            objects.append((left, top, color, bottom-top+1, right-left+1, shape))
    objects.sort(key=lambda obj: (obj[0], obj[1]))
    out = [[0] * w for _ in range(h)]
    row = col = 0
    for i, (_, _, color, oh, ow, shape) in enumerate(objects):
        for dy, dx in shape:
            y, x = row + dy, col + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
        if i + 1 < len(objects):
            row += oh - 1
            col += ow - 1
    return out
